slug: command-undo-captures-state-in-constructor
stack: dotnet
topic: patterns
level: middle
type: find-bug
grading: auto
tags: [command, undo, gof, design-patterns]
code:
  language: csharp
  harness: statements
  source: |
    var editor = new Editor();
    var bigger = new SetFontSizeCommand(editor, 16);
    var huge = new SetFontSizeCommand(editor, 24);

    bigger.Execute();
    huge.Execute();
    huge.Undo();
    Console.WriteLine(editor.FontSize);

    class Editor
    {
        public int FontSize { get; set; } = 12;
    }

    class SetFontSizeCommand
    {
        private readonly Editor _editor;
        private readonly int _newSize;
        private readonly int _previousSize;

        public SetFontSizeCommand(Editor editor, int newSize)
        {
            _editor = editor;
            _newSize = newSize;
            _previousSize = editor.FontSize;
        }

        public void Execute() => _editor.FontSize = _newSize;

        public void Undo() => _editor.FontSize = _previousSize;
    }
bugLineSets: [[25], [25, 28]]
fixedSource: |
  var editor = new Editor();
  var bigger = new SetFontSizeCommand(editor, 16);
  var huge = new SetFontSizeCommand(editor, 24);

  bigger.Execute();
  huge.Execute();
  huge.Undo();
  Console.WriteLine(editor.FontSize);

  class Editor
  {
      public int FontSize { get; set; } = 12;
  }

  class SetFontSizeCommand
  {
      private readonly Editor _editor;
      private readonly int _newSize;
      private int _previousSize;

      public SetFontSizeCommand(Editor editor, int newSize)
      {
          _editor = editor;
          _newSize = newSize;
      }

      public void Execute()
      {
          _previousSize = _editor.FontSize;
          _editor.FontSize = _newSize;
      }

      public void Undo() => _editor.FontSize = _previousSize;
  }
fixedExpect: { kind: output, value: "16" }
